import json, csv, collections

fees = json.load(open("fees.json"))
md = {m["merchant"]: m for m in json.load(open("merchant_data.json"))}
belles = md["Belles_cookbook_store"]

# Belles Jan 2023: monthly volume and fraud level
vol = 0.0
fraud_vol = 0.0
with open("payments.csv", newline="") as f:
    r = csv.DictReader(f)
    for row in r:
        if row["merchant"] == "Belles_cookbook_store" and row["year"] == "2023" and 1 <= int(row["day_of_year"]) <= 31:
            a = float(row["eur_amount"])
            vol += a
            if row["has_fraudulent_dispute"] == "True":
                fraud_vol += a
print("Jan 2023 volume:", vol, "fraud vol:", fraud_vol, "fraud pct:", 100*fraud_vol/vol)

# candidate transactions: NexPay credit, aci in C or B
txns = []
with open("payments.csv", newline="") as f:
    r = csv.DictReader(f)
    for row in r:
        if row["merchant"] == "Belles_cookbook_store" and row["year"] == "2023" and 1 <= int(row["day_of_year"]) <= 31:
            if row["card_scheme"] == "NexPay" and row["is_credit"] == "True" and row["aci"] in ("C", "B"):
                txns.append(row)
print("candidate txns:", len(txns), collections.Counter(t["aci"] for t in txns))

def matches(rule, t):
    if rule.get("card_scheme") and rule["card_scheme"] != t["card_scheme"]:
        return False
    at = rule.get("account_type")
    if at and belles["account_type"] not in at:
        return False
    if rule.get("capture_delay") is not None and rule["capture_delay"] != belles["capture_delay"]:
        return False
    mcc = rule.get("merchant_category_code")
    if mcc and belles["merchant_category_code"] not in mcc:
        return False
    if rule.get("is_credit") is not None and bool(rule["is_credit"]) != (t["is_credit"] == "True"):
        return False
    aci = rule.get("aci")
    if aci and t["aci"] not in aci:
        return False
    if rule.get("intracountry") is not None:
        intra = t["issuing_country"] == t["acquirer_country"]
        if bool(rule["intracountry"]) != intra:
            return False
    return True

for t in txns:
    ms = [r["ID"] for r in fees if matches(r, t)]
    print(t["psp_reference"], t["aci"], t["eur_amount"], ms)
